// Collect Report Data | Mode: Run Once for All Items
// Collapses the per-segment items from Encode to Base into ONE item holding everything the report needs.
// AI Agent nodes output only { output }, so every later node reads these facts BY NODE NAME from here.
// Images stay in Encode to Base: they are large and never go into prompts.
// Every lookup is guarded: a missing upstream node gives an empty value (reported as a warning), never a crash.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const clean = (s, n) => String(s ?? '').replace(/[‐-―]/g, '-').replace(/\s+/g, ' ').trim().slice(0, n);
const num = (v) => {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const m = String(v).replace(/(?<=\d),(?=\d{3})/g, '').match(/\d+(?:\.\d+)?/);   // the first number in the text: "$1,299.00" -> 1299, "4.5 out of 5 stars" -> 4.5
  return m ? Number(m[0]) : null;
};
const first = (...names) => { for (const n of names) { const v = safe(() => $(n).first().json, null); if (v) return v; } return {}; };
// third-party text: links, emails and @mentions out
const scrub = (s) => String(s ?? '')
  .replace(/\b(?:https?:\/\/|www\.)\S*[^\s.,;:!?)\]"']/gi, '[link]')
  .replace(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g, '[email]')
  .replace(/(^|[^\w])@\w{2,}/g, '$1[user]');

// ---- category ----
const parser = first('Input Parser1');
const keyNode = first('Get Category Key');
const category = clean(parser.selectedCategory || keyNode.selectedCategory || 'Rug', 60);
const categoryKey = clean(keyNode.categoryKey || parser.categoryKey || '', 60);

// ---- Amazon products (counts, prices and shares are computed here, never by the AI) ----
const std = first('Save Standardized Data1', 'Save Standardized Data');
const products = arr(std.attributeData && std.attributeData.products);
const tally = (pick, n = 5) => {
  const t = new Map();
  for (const p of products) {
    const vals = [].concat(pick(p) ?? []).map((v) => clean(v, 40)).filter((v) => v && !/^(unknown|other)$/i.test(v));
    for (const v of new Set(vals)) t.set(v, (t.get(v) || 0) + 1);
  }
  return [...t.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, n)
    .map(([value, count]) => ({ value, count, share_pct: Math.round((count / products.length) * 1000) / 10 }));
};
const attr = (k) => (p) => p.attributes && p.attributes[k];
// the standardized products may not carry a numeric price or rating: fall back to the raw Amazon listing with the same url
const listing = new Map(arr(safe(() => $('Reshape Amazon Response').first().json.amazonProducts, [])).map((l) => [String(l.url || ''), l]));
const raw = (p, f) => (listing.get(String(p.url || '')) || {})[f];
const prices = products.map((p) => num(p.details && p.details.price) ?? num(raw(p, 'price'))).filter((x) => x !== null && x > 0).sort((a, b) => a - b);
const ratings = products.map((p) => num(p.details && p.details.rating) ?? num(raw(p, 'rating'))).filter((x) => x !== null && x > 0);
const productFacts = {
  products_analyzed: products.length,
  products_returned: safe(() => Number($('Reshape Amazon Response').first().json.totalProducts) || null, null),
  price: prices.length ? { n: prices.length, min: prices[0], median: prices[Math.floor((prices.length - 1) / 2)], max: prices[prices.length - 1] } : null,
  price_distribution: (std.attributeData && std.attributeData.summary && std.attributeData.summary.price_distribution) || {},
  rating: ratings.length ? { n: ratings.length, mean: Math.round((ratings.reduce((a, b) => a + b, 0) / ratings.length) * 10) / 10 } : null,
  top: {
    color: tally(attr('color')), material: tally(attr('material')), pattern: tally(attr('pattern')), style: tally(attr('style')),
    pile: tally(attr('pile_height')), size: tally(attr('size')),
    features: tally((p) => arr(p.details && p.details.features).map((f) => String(f).replace(/_/g, ' '))),
  },
};

// ---- social captions and hashtags (computed by Merge Image Analysis) ----
const social = first('Merge Social Data1');
const img = first('Merge Image Analysis');
const ts = (img.imageAnalysis && img.imageAnalysis.trend_summary) || {};
const mentions = {};
for (const [g, rows] of Object.entries(ts.attribute_mentions || {})) mentions[g] = arr(rows).slice(0, 6);
const socialFacts = {
  posts_analyzed: Number(ts.total_posts_analyzed) || 0,
  instagram_posts: Number(ts.instagram_count) || 0,
  pinterest_posts: Number(ts.pinterest_count) || 0,
  post_dates: ts.post_dates || {},
  top_hashtags: arr(ts.top_hashtags).slice(0, 8),
  top_hashtags_by_engagement: arr(ts.top_hashtags_by_engagement).slice(0, 8),
  attribute_mentions: mentions,
  attribute_basis: clean(ts.attribute_mentions_basis, 300),
  snapshots: img.dataFreshness || {},
  sources_unavailable: arr(img.sourcesUnavailable),
};

// ---- product attributes next to social mentions, matched by code so the AI cannot mis-compare them ----
// null means "not among the listed (top) values", which is not the same as zero
const same = (v) => String(v ?? '').toLowerCase().replace(/[_-]+/g, ' ').replace(/\bpile\b/g, '').replace(/\s+/g, ' ').trim();
const plain = (v) => String(v ?? '').replace(/_/g, ' ');
const PAIRS = [['material', 'material', 'material'], ['pattern', 'pattern', 'pattern'], ['style', 'style', 'style'], ['pile', 'pile', 'pile'], ['colour', 'color', 'colors'], ['features', 'features', 'features']];
const nProd = productFacts.products_analyzed;
const nPosts = socialFacts.posts_analyzed;
const comparison = PAIRS.map(([group, pKey, sKey]) => {
  const rows = new Map();
  for (const r of arr(productFacts.top[pKey])) rows.set(same(r.value), { value: plain(r.value), amazon_products: r.count, social_posts: null });
  for (const r of arr(mentions[sKey])) {
    const k2 = same(r.value);
    if (rows.has(k2)) rows.get(k2).social_posts = r.posts;
    else rows.set(k2, { value: plain(r.value), amazon_products: null, social_posts: r.posts });
  }
  const values = [...rows.values()].slice(0, 12);
  // the sentences the report uses are written here, so the AI only copies them and cannot mis-sort a value
  const both = values.filter((v) => v.amazon_products !== null && v.social_posts !== null);
  const onlyAmazon = values.filter((v) => v.amazon_products !== null && v.social_posts === null);
  const onlySocial = values.filter((v) => v.amazon_products === null && v.social_posts !== null);
  const highest = (field, total, unit) => {
    const nums = values.map((v) => v[field]).filter((x) => x !== null);
    if (!nums.length) return null;
    const top = Math.max(...nums);
    return `${values.filter((v) => v[field] === top).map((v) => v.value).join(' and ')} (${top} of ${total} ${unit})`;
  };
  return {
    group,
    values,
    summary: {
      on_both: both.map((v) => `${v.value}: ${v.amazon_products} of ${nProd} products and ${v.social_posts} of ${nPosts} posts`),
      only_among_listed_amazon_values: onlyAmazon.map((v) => `${v.value}: ${v.amazon_products} of ${nProd} products`),
      only_among_listed_social_values: onlySocial.map((v) => `${v.value}: ${v.social_posts} of ${nPosts} posts`),
      highest_among_products: highest('amazon_products', nProd, 'products'),
      highest_among_posts: highest('social_posts', nPosts, 'posts'),
    },
  };
});

// ---- trend segments (evidence levels come from Save Trend List) and their images ----
const SUGGESTED = {
  stronger: 'Prioritise for an assortment review',
  moderate: 'Run a small pilot or test',
  weak: 'Monitor; collect more evidence before investing',
  unverified: 'Do not act on this evidence alone',
};
const key = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const imgs = $input.all().map((i) => i.json);
const micro = arr(first('Save Trend List').microSegments);
const source = micro.length ? micro : imgs;   // the image items carry the evidence fields too
const segments = source.slice(0, 3).map((s, idx) => {
  const name = clean(s.name || s.segmentName, 60);
  const match = imgs.find((e) => key(e.segmentName) === key(name)) || (imgs.length === source.length ? imgs[idx] : null);
  const level = ['stronger', 'moderate', 'weak', 'unverified'].includes(s.support_level) ? s.support_level : 'unverified';
  return {
    n: idx + 1,
    name,
    description: clean(s.description, 400),
    visual_characteristics: arr(s.visual_characteristics).slice(0, 5).map((x) => clean(x, 60)),
    color_palette: arr(s.color_palette).slice(0, 5).map((x) => clean(x, 30)),
    typical_materials: arr(s.typical_materials).slice(0, 5).map((x) => clean(x, 30)),
    target_rooms: arr(s.target_rooms).slice(0, 4).map((x) => clean(x, 30)),
    price_positioning: s.price_positioning || null,
    support_level: level,
    confidence: ['low', 'medium', 'high'].includes(s.confidence) ? s.confidence : 'low',
    weakest_attribute: s.weakest_attribute || null,
    trend_signals: arr(s.trend_signals).slice(0, 6).map((x) => clean(x, 200)),
    social_support: arr(s.social_support).slice(0, 6),
    has_image: !!(match && match.hasImage),
    suggested_action: SUGGESTED[level],
  };
});

// ---- blog and market articles (market articles are read straight from Fetch Market Data) ----
const listOf = (raw) => {
  if (raw.length === 1 && raw[0] && typeof raw[0] === 'object') {
    for (const k of ['items', 'posts', 'articles', 'blogs', 'results', 'data']) if (Array.isArray(raw[0][k])) return raw[0][k];
  }
  return raw.filter((r) => r && typeof r === 'object' && r.error === undefined);
};
const textOf = (b) => scrub([b.title, b.summary, b.content, b.description, b.text, ...(Array.isArray(b.key_trends) ? b.key_trends : [])]
  .filter((x) => typeof x === 'string').join('. ')).replace(/\s+/g, ' ').trim();
const toDoc = (kind, prefix) => (b, i) => ({
  id: prefix + (i + 1),
  kind,
  title: clean(scrub(b.title || b.headline || b.name || ''), 120),
  date: clean(b.published_at || b.date || b.scraped_at || '', 20) || null,
  text: textOf(b).slice(0, 6000),
});
// read the articles straight from Fetch Blogs: Merge Social Data1 cuts text at 2000 characters and its phone-number scrub can
// mangle figures such as "CAGR 12.59%"; here only links, emails and @mentions are removed. Falls back to the merged blogs.
const blogsRaw = listOf(safe(() => $('Fetch Blogs').all().map((i) => i.json), []));
const blogs = (blogsRaw.length ? blogsRaw : arr(social.socialData && social.socialData.blogs)).filter((b) => b && typeof b === 'object');
const marketRaw = safe(() => $('Fetch Market Data').all().map((i) => i.json), []);
const blogDocs = blogs.slice(0, 4).map(toDoc('blog', 'B'));
const seenTitles = new Set(blogDocs.map((d) => key(d.title)).filter(Boolean));
const marketDocs = listOf(marketRaw).filter((b) => !seenTitles.has(key(b.title || b.headline || b.name))).slice(0, 2).map(toDoc('market', 'M'));
const kept = [...blogDocs, ...marketDocs].filter((d) => d.text.length >= 20);
// one shared text budget (about 16,000 characters, roughly 4,000 tokens): few articles get more room, many articles get less
const perDoc = Math.min(6000, Math.floor(16000 / Math.max(1, kept.length)));
const docs = kept.map((d) => ({ ...d, text: d.text.slice(0, perDoc) }));

// ---- warnings shown to the reader ----
const warnings = [...arr(ts.data_warnings)];
if (std.errorReason) warnings.push(`Product analysis problem: ${std.errorReason}`);
if (!products.length) warnings.push('No analysed Amazon products were available to the report.');
if (!docs.length) warnings.push('No blog or market articles were available.');
if (!segments.some((s) => s.support_level === 'stronger' || s.support_level === 'moderate')) warnings.push('None of the trend segments has moderate or stronger social support.');

return [{
  json: {
    report: {
      category,
      category_key: categoryKey,
      generated_on: new Date().toISOString().slice(0, 10),
      products: productFacts,
      social: socialFacts,
      comparison,
      segments,
      knowledge_docs: docs,
      warnings: warnings.map((w) => clean(w, 300)).slice(0, 10),
      run_status: {
        products: products.length > 0,
        social_posts: socialFacts.posts_analyzed,
        blog_documents: docs.filter((d) => d.kind === 'blog').length,
        market_documents: docs.filter((d) => d.kind === 'market').length,
        segments: segments.length,
        images: segments.filter((s) => s.has_image).length,
      },
    },
  },
}];

