// Check Sections | Mode: Run Once for All Items
// Gathers the seven AI-written sections plus the Scope section into ONE item for the report assembler, and makes
// the AI's HTML safe and honest:
//  - only a short list of plain tags is kept (no attributes, scripts, links, images); tags are balanced, and an answer that stops
//    in the middle (tags still open at the end) is flagged for review instead of passing silently
//  - a section that failed or came back empty is replaced by a visible placeholder, so the report never has a silent gap
//  - numbers the AI wrote that are not in the facts are listed (section_status = needs_review)
//  - image tokens [[IMAGE_n]] are kept only for real images, once each, and only in the Visual Trend Story
// This node never fails the run.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);

const SECTIONS = [
  { key: 'executive_summary', node: 'Executive Summary Generator', title: 'Executive Summary' },
  { key: 'market_research', node: 'Market Research Generator', title: 'Market and Customer Insights' },
  { key: 'category', node: 'Category Generator', title: 'Category Deep Dive and Sizing' },
  { key: 'attributes', node: 'Attribute Generator', title: 'Attribute and Assortment Analysis' },
  { key: 'visual_trends', node: 'Visual Trends Generator', title: 'Visual Trend Story' },
  { key: 'risks', node: 'Risks Generator', title: 'Risks and Watchouts' },
  { key: 'recommendations', node: 'Recommendations Generator', title: 'Demand Signals and Recommendations' },
];
const ORDER = ['executive_summary', 'scope', 'market_research', 'category', 'attributes', 'visual_trends', 'risks', 'recommendations'];

const ALLOWED = new Set(['h2', 'h3', 'h4', 'p', 'ul', 'ol', 'li', 'strong', 'em', 'table', 'thead', 'tbody', 'tr', 'th', 'td', 'br']);
const sanitize = (html) => {
  let s = String(html ?? '').replace(/[\u2010\u2011]/g, '-').replace(/```[a-z]*\s*/gi, '').replace(/<!--[\s\S]*?-->/g, '');   // models write non-breaking hyphens
  s = s.replace(/<(script|style|iframe|object|embed|svg|math|form|textarea|select|button)\b[\s\S]*?<\/\1\s*>/gi, '');
  const stack = [];
  s = s.replace(/<(\/?)([a-zA-Z][a-zA-Z0-9]*)\b[^>]*>/g, (m, slash, name) => {
    const tag = name.toLowerCase();
    if (!ALLOWED.has(tag)) return '';
    if (tag === 'br') return slash ? '' : '<br>';
    if (!slash) { stack.push(tag); return `<${tag}>`; }
    const at = stack.lastIndexOf(tag);
    if (at === -1) return '';                       // stray closing tag
    return stack.splice(at).reverse().map((t) => `</${t}>`).join('');   // also closes anything left open inside it
  });
  s = s.replace(/<(?![a-zA-Z/])/g, '&lt;');
  const cutTag = /<[^>]*$/.test(s);                  // the text stops inside a tag
  s = s.replace(/<[^>]*$/, '');
  const open = stack.length + (cutTag ? 1 : 0);      // tags still open at the end: the answer was cut off (or badly formed)
  return { html: s + stack.reverse().map((t) => `</${t}>`).join(''), open };
};

const report = safe(() => $('Collect Report Data').first().json.report, {});
const knowledge = safe(() => $('Parse Blog Knowledge').first().json.blogKnowledge, {});
const segments = arr(report.segments);
const withImage = new Set(segments.filter((s) => s.has_image).map((s) => s.n));

// numbers the facts contain: anything else the AI wrote is flagged (whole numbers 0 to 10 are ignored as plain words)
const dropCommas = (t) => String(t).replace(/(?<=\d),(?=\d{3})/g, '');
const normNum = (x) => String(Number(x));
const known = new Set((dropCommas(JSON.stringify([report, knowledge])).match(/\d+(?:\.\d+)?/g) || []).map(normNum));
const textOf = (h) => dropCommas(h.replace(/\[\[IMAGE_\d+\]\]/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' '));
const HYPE = /\b(best-?sell\w*|skyrocket\w*|boom(?:ing)?|surg(?:e|es|ed|ing)|explod\w*|viral)\b/i;

const sections = {};
const status = {};
const notes = {};
const tokensFound = new Set();

for (const sec of SECTIONS) {
  const src = safe(() => $(sec.node).first().json, null);
  const raw = src && src.error === undefined && typeof src.output === 'string' ? src.output : '';
  const cleaned = sanitize(raw);
  let html = cleaned.html;
  // image tokens: only in the visual section, only for segments that have an image, once each
  const seen = new Set();
  html = html.replace(/\[\[IMAGE_(\d+)\]\]/g, (m, n) => {
    const i = Number(n);
    if (sec.key !== 'visual_trends' || !withImage.has(i) || seen.has(i)) return '';
    seen.add(i);
    tokensFound.add(i);
    return m;
  }).replace(/<p>\s*<\/p>/g, '');
  const plain = textOf(html).replace(/\s+/g, ' ').trim();
  const n = [];
  if (plain.length < 40) {
    html = `<h2>${sec.title}</h2><p>This section could not be generated automatically (${src && src.error !== undefined ? 'the AI service returned an error' : 'no usable text was returned'}). Run the workflow again; the other sections are not affected.</p>`;
    status[sec.key] = 'failed';
  } else {
    const unknown = [...new Set((plain.match(/\d+(?:\.\d+)?/g) || []).filter((x) => !(Number.isInteger(Number(x)) && Number(x) <= 10) && !known.has(normNum(x))))].slice(0, 10);
    if (unknown.length) n.push(`Numbers not found in the facts: ${unknown.join(', ')}`);
    if (HYPE.test(plain)) n.push('Contains strong market wording (for example bestselling, booming, surging) that the data cannot support');
    if (cleaned.open > 0) n.push('The text looks cut off or badly formed (tags were still open at the end): check the model\'s maximum output tokens and rerun this section');
    status[sec.key] = n.length ? 'needs_review' : 'ok';
  }
  sections[sec.key] = html;
  notes[sec.key] = n;
}

// scope section is built by code from escaped values
const scope = safe(() => $('Scope Generator').first().json.html, '');
sections.scope = scope || '<h2>Scope of Research</h2><p>The scope section could not be built.</p>';
status.scope = scope ? 'ok' : 'failed';
notes.scope = [];

// which image tokens made it into the Visual Trend Story (the assembler appends any that are missing)
const imagePlan = segments.map((s) => ({ n: s.n, segment: s.name, has_image: s.has_image, placed_in_text: tokensFound.has(s.n) }));
const failed = Object.keys(status).filter((k) => status[k] === 'failed');
const review = Object.keys(status).filter((k) => status[k] === 'needs_review');

return [{
  json: {
    category: report.category || null,
    generated_on: report.generated_on || null,
    section_order: ORDER,
    report_sections: sections,
    section_status: status,
    section_notes: notes,
    failed_sections: failed,
    sections_needing_review: review,
    image_plan: imagePlan,
    data_warnings: arr(report.warnings),
    ready: failed.length === 0 && review.length === 0,
  },
}];
